#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"typedef struct : public SPROLOZ  {	int nHS;    //определяет вид и содержание отображаемой информации	DWORD bkColor; //фон экрана	DWORD CtrlbkColor; //фон экрана по кнопке КОНТР. 	char szKey[32];    //код для отображения	char szNumber[32]; //номер для отображения  }   Queue_PAS_01;void DrawTextData(COLORREF color, Queue_PAS_01 *p, DefinePaint){  HBRUSH hBrush = ::CreateSolidBrush( color );  if( hBrush != NULL )    {    ::FillRect( hDC, &p->mRect, hBrush );    ::DeleteObject( hBrush );    }  int HFild=(p->mRect.right-p->mRect.left)/27;  int VFild=(p->mRect.bottom-p->mRect.top)/10;  RECT rect;  rect.left=p->mRect.left+HFild;  rect.top=p->mRect.top+VFild;  rect.right=p->mRect.right;  int halfofheight=(p->mRect.bottom-p->mRect.top-HFild)/2;  rect.bottom=p->mRect.top+halfofheight;  char str[256];  sprintf_s(str, _countof(str)-1, "ПАС-01 %6.6s %2.2s", p->szKey, p->szNumber );  ::DrawText(hDC, str, -1, &rect, DT_SINGLELINE|DT_VCENTER|DT_LEFT );  __time64_t Time = ::GiveModelTime();  struct tm TM;  _localtime64_s( &TM, &Time );  RECT rect2(rect);  rect2.left+=2*HFild;  rect2.top=rect.bottom;  rect2.bottom=rect2.top+halfofheight;  sprintf_s(str, _countof(str)-1, "%2.2d-%2.2d/%2.2d:%2.2d:%2.2d", TM.tm_mday, TM.tm_mon+1, TM.tm_hour, TM.tm_min, TM.tm_sec);   ::DrawText(hDC, str, -1, &rect2, DT_SINGLELINE|DT_VCENTER|DT_LEFT );}int PaintPAS_01(DefinePaint){  QueueP(Queue_PAS_01);  bool  State=false; //состояние управляющей переменной прописаной в сценарии  if ( p->nHS >= 0 )    {    CShHS& Sh = (CShHS&)q.m_pPipe->SH(p->nHS);    if ( Sh.RetCode == CShBase::rcOK )		State = Sh.mOn;     }  if(!State)    {//рисуем текст с нормальным фоном	DrawTextData(p->bkColor, p, hDC, szQueue, q, beginQ, u);    }  else  {//рисуем текст с фононом для кнопки КОНТР.	  DrawTextData(p->CtrlbkColor, p, hDC, szQueue, q, beginQ, u);  }  return 1;}void AddPAS_01(DefineTegs){  AddQueueEx(Queue_PAS_01);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintPAS_01;  //  char szColor[32];  char szCtrlColor[32];  STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },	{ 'S', "bkcolor", szColor, _countof(szColor) -1  },    { 'S', "ctrlbkcolor", szCtrlColor, _countof(szColor) -1  },	{ 'S', "key", p->szKey, _countof(p->szKey) -1 },	{ 'S', "number", p->szNumber, _countof(p->szNumber) -1  },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  p->nHS = def.AddKind(id_HS, teg[0].value);  p->bkColor=::ParserColors(szColor);  p->CtrlbkColor=::ParserColors(szCtrlColor);}